import {escapeHtml as esc,validRecord,summarize,distance} from './domain.js';
const $=s=>document.querySelector(s), money=n=>Number(n).toLocaleString('ko-KR');
let state;try{state=JSON.parse(localStorage.getItem('ppop-v1')||'null')}catch{}
if(!state||!Array.isArray(state.records)||!Array.isArray(state.saved)||!Array.isArray(state.reports))state={records:[],saved:[],reports:[]};
let stores=[],meta={},selected=null,savedOnly=false,query='',candidateOnly=true,recordsOnly=false,cheapOnly=false,machine='',markers=new Map(),toastTimer;
const save=()=>{try{localStorage.setItem('ppop-v1',JSON.stringify(state));return true}catch{toast('저장 공간이 부족해요. 기록을 내보낸 뒤 다시 시도해 주세요.');return false}};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
const map=L.map('map',{zoomControl:false,minZoom:6,maxZoom:19}).setView([37.555,126.925],15);
const tiles=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);
let tileErrors=0;tiles.on('tileerror',()=>{if(++tileErrors>3)$('#tile-error').hidden=false});tiles.on('tileload',()=>{$('#tile-error').hidden=true;tileErrors=0});
const recordsFor=id=>state.records.filter(r=>r.storeId===id), allStores=()=>[...state.reports,...stores];
function filtered(){return allStores().filter(s=>(!candidateOnly||s.candidate)&&(!savedOnly||state.saved.includes(s.id))&&(!query||(s.name+' '+s.address).toLowerCase().includes(query))&&(!recordsOnly||recordsFor(s.id).length)&&(!cheapOnly||recordsFor(s.id).some(r=>r.price<=1000))&&(!machine||recordsFor(s.id).some(r=>r.machine===machine)))}
function art(s){const n=[...s.id].reduce((a,c)=>a+c.charCodeAt(0),0);return {emoji:['🧸','🐰','🐻','🐱'][n%4],color:['','pink','mint','lilac'][n%4]}}
function render(){const center=map.getCenter(),bounds=map.getBounds(),matches=filtered(),global=!!query||savedOnly;let visible=matches.filter(s=>global||bounds.contains([s.lat,s.lng]));visible.sort((a,b)=>distance(center.lat,center.lng,a.lat,a.lng)-distance(center.lat,center.lng,b.lat,b.lng));const shown=visible.slice(0,200);
$('#result-count').textContent=`${savedOnly?'저장한 가게':query?'검색 결과':'주변 가게'} ${money(visible.length)}곳`;
$('#list-context').textContent=visible.length>200?'가까운 200곳 표시':global?'전국 기준':'현재 지도 기준';
$('#national-count').textContent=`전국 인형뽑기 후보 ${money(meta.candidates||0)}곳 · 공공데이터`;
$('#record-count').textContent=state.records.length;
$('#store-list').innerHTML=shown.length?shown.slice(0,60).map(s=>{const a=art(s),r=recordsFor(s.id),sum=summarize(r),d=distance(center.lat,center.lng,s.lat,s.lng);return `<article class="store-card" tabindex="0" role="button" data-store="${esc(s.id)}" aria-label="${esc(s.name)} 상세 보기"><div class="store-art ${a.color}">${a.emoji}</div><div class="store-main"><h2 class="store-name">${esc(s.name)}</h2><p class="store-address">${esc(s.address)}</p><div class="store-meta"><span>${d<1?Math.round(d*1000)+'m':d.toFixed(1)+'km'}</span><span>${sum.rating?'★ '+sum.rating+' · 내 기록 '+r.length:'첫 기록을 남겨보세요'}</span></div><div style="margin-top:7px"><span class="tag ${s.candidate?'orange':''}">${s.source==='user'?'직접 제보 · 미검증':s.candidate?'인형뽑기 후보':'오락실 · 확인 필요'}</span>${r.length?` <span class="tag">${money(r[r.length-1].price)}원 / 회</span>`:''}</div></div><button class="save-btn ${state.saved.includes(s.id)?'saved':''}" data-save="${esc(s.id)}" aria-label="${state.saved.includes(s.id)?'저장 해제':'가게 저장'}">${state.saved.includes(s.id)?'♥':'♡'}</button></article>`}).join(''):`<div class="empty">${savedOnly?'아직 저장한 가게가 없어요.<br>마음에 드는 가게의 ♡를 눌러보세요.':'조건에 맞는 가게가 없어요.<br>지도를 옮기거나 검색·필터를 바꿔보세요.'}<br><button id="reset-filters">필터 초기화</button></div>`;
for(const m of markers.values())map.removeLayer(m);markers.clear();for(const s of shown){const a=art(s),r=recordsFor(s.id),icon=L.divIcon({className:'pin-wrap',html:`<div class="pin ${selected?.id===s.id?'active':''} ${s.source==='user'?'reported':''}"><span>${a.emoji}</span></div>${r.length?`<div class="pin-price">${money(r[r.length-1].price)}원</div>`:''}`,iconSize:[42,55],iconAnchor:[21,46]});const marker=L.marker([s.lat,s.lng],{icon,title:s.name}).addTo(map).on('click',()=>openDetail(s.id));markers.set(s.id,marker)}}
map.on('moveend',render);
function openDetail(id){selected=allStores().find(s=>s.id===id);if(!selected)return;const s=selected,r=recordsFor(id),sum=summarize(r),latest=r[r.length-1],a=art(s);$('#detail-content').innerHTML=`<div class="detail-hero"><span>${a.emoji}</span><span>🕹️</span><span>✨</span><span class="hero-label">오늘의 작은 행복을 찾아서</span><button class="close" data-close="detail-dialog" aria-label="닫기">×</button></div><div class="detail-body"><span class="tag orange">${s.source==='user'?'직접 제보 · 확인 필요':'공공데이터 · '+(s.candidate?'인형뽑기 후보':'오락실')}</span><h2>${esc(s.name)}</h2><p class="address">${esc(s.address)}</p><div class="detail-actions"><button id="write-record" class="primary">＋ 도전 · 리뷰 기록</button><button class="outline" data-save="${esc(id)}">${state.saved.includes(id)?'♥ 저장됨':'♡ 가게 저장'}</button></div><div class="stats"><div><strong>${sum.attempts||'—'}</strong><small>나의 총 도전</small></div><div><strong>${r.length?sum.wins:'—'}</strong><small>뽑은 인형 수</small></div><div><strong>${r.length?sum.rate+'%':'—'}</strong><small>나의 성공률</small></div></div><div class="section-title"><h3>가게 정보</h3><span>최근 내 기록 기준</span></div><div class="info-grid"><div class="info-cell"><small>한 게임 가격</small>${latest?money(latest.price)+'원':'아직 정보가 없어요'}</div><div class="info-cell"><small>머신 종류</small>${latest?esc(latest.machine):'첫 정보를 남겨주세요'}</div><div class="info-cell"><small>인형 종류</small>${latest?esc(latest.doll||'미입력'):'아직 정보가 없어요'}</div><div class="info-cell"><small>내 평점</small>${sum.rating?'★ '+sum.rating+' / 5':'아직 리뷰가 없어요'}</div></div><div class="section-title"><h3>나의 도전과 리뷰 <span>${r.length}</span></h3></div>${r.length?r.slice().reverse().map(e=>`<article class="review"><div class="review-top"><strong>${'★'.repeat(e.rating)}${'☆'.repeat(5-e.rating)}</strong><small>${esc(e.date)}</small></div><p>${esc(e.review||'리뷰 없이 도전만 기록했어요.')}</p><small>${e.attempts}회 도전 · ${e.wins}개 득템 · ${money(e.attempts*e.price)}원<br>${esc(e.doll||'인형 미입력')} · ${esc(e.machine)}</small><div style="text-align:right"><button class="text-link" data-delete="${esc(e.id)}">기록 삭제</button></div></article>`).join(''):'<div class="empty">아직 기록이 없어요.<br>첫 도전의 주인공이 되어주세요 🧸</div>'}<p class="local-notice">기록은 이 브라우저에만 저장돼요. 성공률은 내 도전 기록의 통계이며 기계의 당첨 확률을 의미하지 않아요. 실제 영업·가격·재고는 방문 시 확인해 주세요.</p><a class="text-link" href="https://map.kakao.com/link/map/${encodeURIComponent(s.name)},${s.lat},${s.lng}" target="_blank" rel="noopener noreferrer">카카오맵에서 위치 보기 ↗</a></div>`;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();render()}
function recordForm(){const s=selected;$('#form-title').textContent='오늘의 도전을 기록해요';$('#entry-form').innerHTML=`<p class="help">${esc(s.name)} · 기록은 이 브라우저에만 저장됩니다.</p><label for="date">방문 날짜</label><input id="date" name="date" type="date" max="${new Date().toLocaleDateString('en-CA')}" value="${new Date().toLocaleDateString('en-CA')}" required><div class="form-row"><div><label for="attempts">도전 횟수</label><input id="attempts" name="attempts" type="number" min="1" max="10000" step="1" value="10" required></div><div><label for="wins">뽑은 인형 수</label><input id="wins" name="wins" type="number" min="0" step="1" value="1" required></div></div><label for="price">한 게임 가격 (원)</label><input id="price" name="price" type="number" min="0" max="100000" step="1" value="1000" required><div class="form-row"><div><label for="doll">인형 종류</label><input id="doll" name="doll" placeholder="예: 산리오, 포켓몬" maxlength="80"></div><div><label for="machine">머신 종류</label><select id="machine" name="machine"><option>일반 크레인</option><option>미니 크레인</option><option>대형 크레인</option><option>집게 2발</option><option>집게 3발</option><option>기타 / 모름</option></select></div></div><label for="rating">이번 방문은 어땠나요?</label><select id="rating" name="rating"><option value="5">★★★★★ 정말 좋아요</option><option value="4">★★★★☆ 좋아요</option><option value="3">★★★☆☆ 보통이에요</option><option value="2">★★☆☆☆ 아쉬워요</option><option value="1">★☆☆☆☆ 별로예요</option></select><label for="review">리뷰</label><textarea id="review" name="review" maxlength="1000" placeholder="집게 느낌, 인형 상태, 가게 분위기를 남겨주세요."></textarea><p id="form-error" class="error" role="alert"></p><button class="primary submit">도전 기록 저장하기</button>`;$('#entry-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),r={id:crypto.randomUUID(),storeId:s.id,date:String(f.get('date')),attempts:Number(f.get('attempts')),wins:Number(f.get('wins')),price:Number(f.get('price')),rating:Number(f.get('rating')),doll:String(f.get('doll')).trim(),machine:String(f.get('machine')),review:String(f.get('review')).trim()};if(!validRecord(r)){$('#form-error').textContent='도전·득템 수를 확인해 주세요. 득템 수는 도전 횟수 이하여야 해요.';return}state.records.push(r);if(!save()){state.records.pop();return}$('#form-dialog').close();openDetail(s.id);toast('오늘의 도전을 저장했어요 🧸')};$('#form-dialog').showModal()}
function reportForm(){$('#form-title').textContent='새로운 뽑기방을 알려주세요';const c=map.getCenter();$('#entry-form').innerHTML=`<p class="help">현재 지도 중심 좌표를 사용해요. 정확한 위치로 지도를 옮긴 뒤 제보해 주세요.<br>제보는 이 브라우저에만 저장되며 미검증으로 표시됩니다.</p><label for="store-name">가게 이름</label><input id="store-name" name="name" maxlength="100" required><label for="store-address">주소</label><input id="store-address" name="address" maxlength="200" required><div class="form-row"><div><label for="lat">위도</label><input id="lat" name="lat" type="number" step="any" min="33" max="39" value="${c.lat.toFixed(6)}" required></div><div><label for="lng">경도</label><input id="lng" name="lng" type="number" step="any" min="124" max="132" value="${c.lng.toFixed(6)}" required></div></div><button class="primary submit">가게 제보 저장하기</button>`;$('#entry-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),s={id:'user-'+crypto.randomUUID(),name:String(f.get('name')).trim(),address:String(f.get('address')).trim(),lat:Number(f.get('lat')),lng:Number(f.get('lng')),candidate:true,source:'user'};if(!s.name||!s.address){toast('가게 이름과 주소를 입력해 주세요');return}state.reports.push(s);if(!save()){state.reports.pop();return}$('#form-dialog').close();map.setView([s.lat,s.lng],16);openDetail(s.id);toast('새로운 가게를 저장했어요')};$('#form-dialog').showModal()}
document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close){$('#'+close.dataset.close).close();return}const sv=e.target.closest('[data-save]');if(sv){const previous=[...state.saved],id=sv.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];if(!save()){state.saved=previous;return}render();if($('#detail-dialog').open)openDetail(id);return}const del=e.target.closest('[data-delete]');if(del){const previous=state.records;state.records=state.records.filter(r=>r.id!==del.dataset.delete);if(!save()){state.records=previous;return}openDetail(selected.id);toast('기록을 삭제했어요');return}const card=e.target.closest('[data-store]');if(card){const s=allStores().find(s=>s.id===card.dataset.store);map.setView([s.lat,s.lng],16);openDetail(s.id)}if(e.target.closest('#write-record'))recordForm();if(e.target.closest('#reset-filters')){candidateOnly=true;recordsOnly=cheapOnly=false;machine=query='';$('#search').value='';savedOnly=false;updateFilters();render()}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.store-card')){e.preventDefault();e.target.click()}});
function updateFilters(){$('#candidate-filter').classList.toggle('selected',candidateOnly);$('#review-filter').classList.toggle('selected',recordsOnly);$('#price-filter').classList.toggle('selected',cheapOnly);$('#machine-filter').classList.toggle('selected',!!machine);$('#machine-filter').textContent=machine?'▣ '+machine:'▣ 머신 종류';$('#saved-tab').classList.toggle('active',savedOnly);$('#nearby-tab').classList.toggle('active',!savedOnly)}
$('#candidate-filter').onclick=()=>{candidateOnly=!candidateOnly;updateFilters();render()};$('#review-filter').onclick=()=>{recordsOnly=!recordsOnly;updateFilters();render()};$('#price-filter').onclick=()=>{cheapOnly=!cheapOnly;updateFilters();render()};$('#machine-filter').onclick=()=>{$('#form-title').textContent='어떤 머신을 찾으세요?';$('#entry-form').innerHTML='<label for="machine-choice">내 기록의 머신 종류</label><select id="machine-choice"><option value="">전체 머신</option>'+['일반 크레인','미니 크레인','대형 크레인','집게 2발','집게 3발','기타 / 모름'].map(x=>`<option ${machine===x?'selected':''}>${x}</option>`).join('')+'</select><p class="help">머신 정보가 입력된 내 기록을 기준으로 필터링해요.</p><button class="primary submit">적용하기</button>';$('#entry-form').onsubmit=e=>{e.preventDefault();machine=$('#machine-choice').value;$('#form-dialog').close();updateFilters();render()};$('#form-dialog').showModal()};
$('#saved-tab').onclick=()=>{savedOnly=true;updateFilters();render()};$('#nearby-tab').onclick=()=>{savedOnly=false;updateFilters();render()};
$('#search-form').onsubmit=e=>{e.preventDefault();query=$('#search').value.trim().toLowerCase();render();const s=filtered()[0];if(s&&query)map.setView([s.lat,s.lng],14)};let searchTimer;$('#search').oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{query=$('#search').value.trim().toLowerCase();render()},200)};
for(const b of document.querySelectorAll('[data-center]'))b.onclick=()=>{query='';$('#search').value='';map.setView(b.dataset.center.split(',').map(Number),15);render()};
$('#zoom-in').onclick=()=>map.zoomIn();$('#zoom-out').onclick=()=>map.zoomOut();$('#report-store').onclick=reportForm;$('#mobile-toggle').onclick=()=>{document.body.classList.toggle('expanded');$('#mobile-toggle').textContent=document.body.classList.contains('expanded')?'⌄ 지도 크게 보기':'☰ 매장 목록'};
$('#locate').onclick=()=>{if(!navigator.geolocation){toast('이 브라우저는 위치 기능을 지원하지 않아요');return}toast('현재 위치를 확인하고 있어요');navigator.geolocation.getCurrentPosition(p=>{map.setView([p.coords.latitude,p.coords.longitude],15);toast('내 주변 뽑기방을 찾아보세요')},()=>toast('위치를 확인할 수 없어요. 지역명으로 검색해 주세요.'),{timeout:10000,maximumAge:60000})};
function showInfo(html){$('#info-content').innerHTML=html;$('#info-dialog').showModal()}
$('#data-info').onclick=()=>showInfo(`<p>전국 지방행정 인허가 데이터의 청소년게임제공업 중 영업 등록 상태의 업소를 사용합니다.</p><p>수집일: ${esc(meta.fetchedAt||'—')}<br>원본 ${money(meta.total||0)}행 · 영업 등록 ${money(meta.active||0)}곳<br>좌표 보유 ${money(meta.mapped||0)}곳 · 인형뽑기 후보 ${money(meta.candidates||0)}곳<br>좌표 누락·범위 오류로 제외 ${money(meta.missingCoordinates||0)}곳</p><p>후보 분류: ${esc(meta.classification||'')}<br>좌표: ${esc(meta.crs||'')}</p><p><a href="https://www.data.go.kr/data/15045069/fileData.do" target="_blank" rel="noopener">행정안전부 원천 데이터 ↗</a> · 무료 · 이용허락범위 제한 없음</p><p>가격·머신·인형·리뷰는 공공데이터에 없는 방문자 입력 정보입니다. 예시 리뷰나 가짜 평점은 넣지 않았습니다.</p><p>이 POC는 로그인·서버 저장·다른 사용자와의 공유 기능이 없습니다. 기록과 제보는 이 브라우저에만 남고 브라우저 데이터를 지우면 삭제됩니다. 사진 참고 자료는 배포 파일에 포함하지 않았습니다.</p>`);
$('#my-records').onclick=()=>{const sum=summarize(state.records);showInfo(`<h3>나의 뽑기노트</h3><div class="notes-summary">${state.records.length}번의 방문 · ${sum.attempts}회 도전 · ${sum.wins}개 득템<br>총 사용 금액 <strong>${money(sum.spent)}원</strong></div><p>이 브라우저에 저장된 기록이에요. 파일로 내보내 안전하게 보관할 수 있어요.</p><button id="export-records" class="primary">내 기록 JSON 내보내기</button>`);$('#export-records').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ppop-my-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}};
Promise.all([fetch('data/stores.json').then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('data/meta.json').then(r=>{if(!r.ok)throw Error();return r.json()})]).then(([s,m])=>{stores=s;meta=m;render()}).catch(()=>{$('#store-list').innerHTML='<div class="empty">매장 데이터를 불러오지 못했어요.<br>페이지를 새로고침해 주세요.</div>';toast('데이터 연결에 실패했어요')});
